type LoseContextExt = { loseContext(): void };

function releaseProbeContext(gl: WebGLRenderingContext | WebGL2RenderingContext | null) {
  try {
    const lose = (gl?.getExtension?.('WEBGL_lose_context') as LoseContextExt | null) ?? null;
    lose?.loseContext();
  } catch {
    // Some drivers expose the extension but fail to act on it; the probe
    // context is still garbage-collected, so ignoring the error is safe.
  }
}

/**
 * Detects WebGL support with a throwaway probe context.
 *
 * The probe context is actively released (WEBGL_lose_context) when available.
 * Leaving probe contexts alive is expensive on GPU/VM-limited stacks and — when
 * created on every render — can exhaust the browser's live-context budget and
 * force real scene contexts to be evicted (`webglcontextlost`). Callers should
 * therefore probe once per page/device, not on every render.
 */
export function hasWebGLSupport(canvasFactory = () => document.createElement('canvas')) {
  try {
    const canvas = canvasFactory();
    const gl = (canvas.getContext('webgl2') || canvas.getContext('webgl')) as
      | WebGLRenderingContext
      | WebGL2RenderingContext
      | null;
    releaseProbeContext(gl);
    return Boolean(gl);
  } catch {
    return false;
  }
}
